Index: scripts/fleet/post_task_reap.py
===================================================================
--- scripts/fleet/post_task_reap.py	
+++ scripts/fleet/post_task_reap.py	
@@ -1,819 +1,827 @@
 #!/usr/bin/env python3
 """Safe post-task reaper for dispatch worktrees.

 Reaps the dispatch worktree bound to one task_id only after the task is terminal,
 the worktree is clean, and (when a PID is recorded) the process is dead.  ACP
 runtime paths are reaped only when they are explicitly listed in the task state
 (``acp_runtime_paths``), the task is terminal, the path is clean, and no live
 process holds it.

 A terminal dispatch worktree is reaped even when its task never opened a GitHub
 PR (measure-only, timeout, cancelled, …) as long as ownership, cleanliness, and
 dead-PID guards all hold and no open PR is present.  The deletion itself always
 goes through the canonical P0 reaper boundary.

 Default mode is dry-run; pass --apply to delete anything.
 """

 from __future__ import annotations

 import argparse
 import json
 import os
 import subprocess
 from pathlib import Path
 from typing import Any

 from scripts.common.repo_root import main_checkout_root
+from scripts.fleet import pr_identity
 from scripts.orchestration import reap_worktrees, reaper_lifecycle
 from scripts.path_safety import assert_delete_target

 ROOT = main_checkout_root(Path(__file__).resolve().parents[2])
 _TASKS_DIR = ROOT / "batch_state" / "tasks"
 _DISPATCH_WORKTREES_ROOT = ROOT / ".worktrees" / "dispatch"
 _ACP_RUNTIME_ROOT = _DISPATCH_WORKTREES_ROOT / "acp"

 _ACTIVE_STATUSES = frozenset({"spawning", "running"})
 _TERMINAL_STATUSES = frozenset(
     {
         "done",
         "failed",
         "timeout",
         "rate_limited",
         "cancelled",
         "crashed",
         "dry_run",
         "needs_finalize",
         "no_deliverable",
     }
 )

 _GIT_ENV_DENYLIST = {
     "GIT_DIR",
     "GIT_WORK_TREE",
     "GIT_INDEX_FILE",
     "GIT_OBJECT_DIRECTORY",
     "GIT_ALTERNATE_OBJECT_DIRECTORIES",
     "GIT_NAMESPACE",
     "GIT_CEILING_DIRECTORIES",
     "GIT_DISCOVERY_ACROSS_FILESYSTEM",
     "GIT_COMMON_DIR",
 }


 def _sanitized_git_env() -> dict[str, str]:
     return {
         key: value
         for key, value in os.environ.items()
         if key not in _GIT_ENV_DENYLIST and not key.startswith("PRE_COMMIT")
     }


 def _run_git(
     args: list[str],
     *,
     cwd: Path,
     timeout: int | None = 30,
     check: bool = False,
 ) -> subprocess.CompletedProcess[str]:
     return subprocess.run(
         ["git", *args],
         cwd=cwd,
         capture_output=True,
         text=True,
         check=check,
         timeout=timeout,
         env=_sanitized_git_env(),
     )


 def _load_task_state(tasks_dir: Path, task_id: str) -> dict[str, Any] | None:
     safe = task_id.replace("/", "_").replace("\\", "_")
     path = tasks_dir / f"{safe}.json"
     if not path.is_file():
         return None
     try:
         data = json.loads(path.read_text(encoding="utf-8"))
     except (OSError, json.JSONDecodeError):
         return None
     return data if isinstance(data, dict) else None


 def _worktree_path_from_state(state: dict[str, Any]) -> Path | None:
     """Return the bound worktree path recorded in task state, if any."""
     for key in ("worktree_path", "cwd"):
         value = state.get(key)
         if value:
             try:
                 return Path(str(value)).resolve()
             except OSError:
                 continue
     return None


 def _acp_runtime_paths_from_state(state: dict[str, Any]) -> list[Path]:
     """Return ACP runtime paths explicitly bound to this task in state.

     Paths are taken from ``acp_runtime_paths`` (a list of strings).  Name or
     substring matching is never used; an unbound path is not ours to reap.
     """
     raw = state.get("acp_runtime_paths")
     if not isinstance(raw, list):
         return []
     candidates: list[Path] = []
     for item in raw:
         if not item:
             continue
         try:
             candidates.append(Path(str(item)).resolve())
         except OSError:
             continue
     return candidates


 def _is_under_dispatch_worktrees(path: Path) -> bool:
     """True for paths inside .worktrees/dispatch/ but outside the ACP runtime subtree."""
     try:
         rel = path.resolve().relative_to(_DISPATCH_WORKTREES_ROOT)
     except ValueError:
         return False
     return rel.parts[:1] != ("acp",)


 def _acp_runtime_root(repo_root: Path) -> Path:
     """Return the dedicated ACP-runtime subtree for one repository root."""
     return repo_root.resolve() / ".worktrees" / "dispatch" / "acp"


 def _is_under_acp_runtime_root(path: Path, repo_root: Path = ROOT) -> bool:
     """True for paths inside .worktrees/dispatch/acp/."""
     runtime_root = _acp_runtime_root(repo_root).resolve()
     try:
         resolved_path = path.resolve()
         resolved_path.relative_to(runtime_root)
     except ValueError:
         return False
     return resolved_path != runtime_root


 def _is_registered_worktree(path: Path, repo_root: Path) -> bool:
     """True when path is a registered git worktree."""
     proc = _run_git(["worktree", "list", "--porcelain"], cwd=repo_root)
     if proc.returncode != 0:
         return False
     resolved = path.resolve()
     for line in (proc.stdout or "").splitlines():
         if line.startswith("worktree "):
             candidate = Path(line[len("worktree ") :].strip()).resolve()
             if candidate == resolved:
                 return True
     return False


 def _worktree_is_dirty(path: Path, *, ignore_deleted_tracked: bool = False) -> bool | None:
     proc = _run_git(["status", "--porcelain"], cwd=path)
     if proc.returncode != 0:
         return None
     lines = [line for line in (proc.stdout or "").splitlines() if line.strip()]
     if ignore_deleted_tracked:
         # No-checkout ACP runtime worktrees report every tracked file as deleted.
         # Ignore those baseline deletions; flag only untracked/modified additions.
         lines = [line for line in lines if not (line[0] == "D" or line[1] == "D")]
     return bool(lines)


 def _git_worktree_is_locked(path: Path, repo_root: Path) -> bool:
     """Return True if git reports the worktree as locked.  Fail closed."""
     proc = _run_git(["worktree", "list", "--porcelain"], cwd=repo_root)
     if proc.returncode != 0:
         return True
     resolved = path.resolve()
     entry_path: Path | None = None
     locked = False
     for line in (proc.stdout or "").splitlines():
         if line.startswith("worktree "):
             if entry_path == resolved:
                 return locked
             entry_path = Path(line[len("worktree ") :].strip()).resolve()
             locked = False
         elif line.startswith("locked"):
             locked = True
     if entry_path == resolved:
         return locked
     return True


 def _pid_alive(pid: int) -> bool | None:
     """Return True if ``pid`` is alive, False if dead, None if probe failed.

     Fail-closed callers must treat ``None`` as 'retain'.
     """
     if pid <= 0:
         return False
     try:
         os.kill(pid, 0)
     except ProcessLookupError:
         return False
     except PermissionError:
         return True
     except OSError:
         return None
     return True


 def _probe_path_liveness(path: Path) -> bool | None:
     """Return True if a live process holds ``path``, False if not, None on error.

     Uses ``lsof +D`` when available.  Any probe failure (missing binary, timeout,
     nonzero exit, or subprocess error) returns ``None`` so the caller can fail
     closed and retain the path.
     """
     try:
         proc = subprocess.run(
             ["lsof", "+D", str(path)],
             capture_output=True,
             text=True,
             timeout=10,
             check=False,
         )
     except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.SubprocessError):
         return None
     if proc.returncode != 0:
         return None
     return any(line and not line.startswith("COMMAND") for line in (proc.stdout or "").splitlines())


 def _unlock_worktree(path: Path, repo_root: Path) -> None:
     """Best-effort unlock of a git worktree before removal."""
     _run_git(["worktree", "unlock", str(path)], cwd=repo_root)


 def _remove_worktree(path: Path, repo_root: Path) -> tuple[bool, str | None]:
     """Force-remove one state-bound ACP runtime beneath its dedicated subtree.

     This is deliberately not the regular dispatch deletion path: callers must
     first establish terminal task ownership, cleanliness, and no live process.
     Regular dispatch worktrees always go through ``reap_worktrees`` instead.
     """
     if not _is_under_acp_runtime_root(path, repo_root):
         return False, "ACP runtime path is outside .worktrees/dispatch/acp/"
     try:
         target = assert_delete_target(path, repo_root=repo_root)
     except ValueError as exc:
         return False, f"delete guard refused ACP runtime target: {exc}"
     cmd = ["worktree", "remove", "--force", str(target)]
     proc = _run_git(cmd, cwd=repo_root)
     if proc.returncode != 0:
         detail = (proc.stderr or proc.stdout or "git worktree remove failed").strip()
         return False, detail
     if path.exists():
         return False, f"worktree path still exists after remove: {path}"
     return True, None


 def _parse_state_pid(state: dict[str, Any]) -> int | None:
     """Return a positive integer PID from task state, or None."""
     raw = state.get("pid")
     if isinstance(raw, bool):
         return None
     if isinstance(raw, int):
         return raw if raw > 0 else None
     if isinstance(raw, str) and raw.isdigit():
         return int(raw) if int(raw) > 0 else None
     return None


 def _reap_main_worktree(
     *,
     task_id: str,
     state: dict[str, Any],
     repo_root: Path,
     apply: bool,
 ) -> dict[str, Any]:
     """Evaluate and optionally reap the dispatch worktree bound to task_id."""
     status = state.get("status")
     status_str = str(status) if status is not None else None

     if status_str in _ACTIVE_STATUSES or status_str in (None, ""):
         return {
             "path": None,
             "action": "retained",
             "reason": f"task still active (status={status_str})",
             "error": None,
         }
     if status_str not in _TERMINAL_STATUSES:
         return {
             "path": None,
             "action": "retained",
             "reason": f"task status not terminal (status={status_str})",
             "error": None,
         }

     bound_path = _worktree_path_from_state(state)
     if bound_path is None:
         return {
             "path": None,
             "action": "retained",
             "reason": "unknown ownership: no worktree_path/cwd in task state",
             "error": None,
         }

     if not bound_path.exists():
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "bound worktree path does not exist",
             "error": None,
         }

     if not _is_under_dispatch_worktrees(bound_path):
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "unknown ownership: path is outside .worktrees/dispatch/",
             "error": None,
         }

     state_task_id = state.get("task_id")
     if state_task_id not in (None, task_id):
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "unknown ownership: task-state task_id does not match requested task",
             "error": None,
         }
     try:
         relative = bound_path.relative_to(_DISPATCH_WORKTREES_ROOT)
     except ValueError:  # guarded above; retain if the filesystem changed.
         relative = ()
     expected_agent = str(state.get("agent") or "")
     if (
         len(relative.parts) != 2
         or relative.parts[1] != task_id
         or not expected_agent
         or relative.parts[0] != expected_agent
     ):
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "unknown ownership: task binding does not match dispatch path",
             "error": None,
         }

     if reaper_lifecycle.is_reap_pending(repo_root, bound_path):
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "reap-pending reservation blocks a new task bind",
             "error": None,
         }

     if not _is_registered_worktree(bound_path, repo_root):
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "unknown ownership: path is not a registered git worktree",
             "error": None,
         }

     if _git_worktree_is_locked(bound_path, repo_root):
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "registered worktree is locked",
             "error": None,
         }

     dirty = _worktree_is_dirty(bound_path)
     if dirty is None:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "unable to determine worktree cleanliness",
             "error": None,
         }
     if dirty:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "worktree has uncommitted changes",
             "error": None,
         }

     pid = _parse_state_pid(state)
     if pid is not None:
         alive = _pid_alive(pid)
         if alive is True:
             return {
                 "path": str(bound_path),
                 "action": "retained",
                 "reason": f"live process holds worktree (pid={pid})",
                 "error": None,
             }
         if alive is None:
             return {
                 "path": str(bound_path),
                 "action": "retained",
                 "reason": f"liveness probe failed for recorded pid={pid}",
                 "error": None,
             }

     row = _reap_via_canonical(
         repo_root=repo_root,
         bound_path=bound_path,
         apply=apply,
         include_terminal_dispatches=True,
     )
     if row is None:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "canonical P0 reaper did not evaluate bound path",
             "error": None,
         }

     # The canonical reaper only reaps a settled dispatch without a PR when its
     # active-task API probe succeeds and the status is in its narrow terminal
     # set (done/failed/no_deliverable).  post_task_reap has already proven the
     # broader terminal contract itself: status is terminal, the bound tree is
     # clean, and the recorded PID is dead.  When the canonical reaper declines
     # solely because no GitHub PR qualifies, drive the same guarded deletion
     # through its public success-worktree boundary, after re-proving that no
     # open PR appeared and (on apply) that no live process holds the tree.
     if row["action"] == "skipped" and row["reason"] == "no reap condition matched":
         return _reap_terminal_without_pr(
             task_id=task_id,
             status_str=status_str,
             bound_path=bound_path,
             row=row,
             repo_root=repo_root,
             apply=apply,
             branch=row.get("branch") or f"{expected_agent}/{task_id}",
         )
     return row


 def _reap_via_canonical(
     *,
     repo_root: Path,
     bound_path: Path,
     apply: bool,
     include_terminal_dispatches: bool,
 ) -> dict[str, Any] | None:
     """Delegate to the canonical P0 reaper for one bound dispatch worktree."""
     try:
         rows = reap_worktrees.reap_worktrees(
             repo_root=repo_root,
             apply=apply,
             preserve_then_reap=False,
             prune_merged_branches=True,
             target_paths=[bound_path],
             merged_pr_only=True,
             include_terminal_dispatches=include_terminal_dispatches,
             require_activity_probe=apply,
         )
     except RuntimeError as exc:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "canonical P0 reaper guard failed",
             "error": str(exc),
         }
     if not rows:
         return None
     row = rows[0]
     return {
         "path": row.path,
         "action": row.action,
         "reason": row.reason,
         "error": row.error,
         "pr": row.pr,
         "recovery_ref": row.recovery_ref,
         "branch": row.branch,
     }


 def _no_open_pr_for_branch(
     *,
     repo_root: Path,
     branch: str | None,
 ) -> tuple[bool, str | None]:
     """Return (no_open_pr, failure) for the branch that owns the bound tree.

-    Reuses the canonical reaper's candidate derivation so detached and
-    dispatch-layout worktrees are checked under the same branch names that the
-    canonical path would have probed.  A probe error is fail-closed.
+    PR identity binding lives in one shared probe (scripts.fleet.pr_identity,
+    #7127) — the same binding hramatka_hygiene_check uses — so the reaper and
+    the closeout gate cannot drift apart again.  This caller keeps only its
+    fail-closed direction: an unknown answer retains the worktree instead of
+    deleting it.
     """
     if not branch:
         return False, "no branch identity to probe for an open PR"
-    prs, error = reap_worktrees._query_pr_states(repo_root, branch)
-    if error is not None:
+    repo = pr_identity.resolve_repo_slug(repo_root)
+    has_open_pr, error = pr_identity.probe_open_pr_for_branch(
+        repo_root=repo_root,
+        repo=repo,
+        branch=branch,
+    )
+    if has_open_pr is None:
         return False, f"PR guard unavailable; {error}"
-    return all(pr.state != "OPEN" for pr in prs), None
+    return not has_open_pr, None


 def _reap_terminal_without_pr(
     *,
     task_id: str,
     status_str: str,
     bound_path: Path,
     row: dict[str, Any],
     repo_root: Path,
     apply: bool,
     branch: str | None,
 ) -> dict[str, Any]:
     """Reap a clean, dead-PID, dispatch-layout worktree that never had a PR."""
     reason = f"settled dispatch task-id={task_id} status={status_str}"

     no_open_pr, guard_error = _no_open_pr_for_branch(repo_root=repo_root, branch=branch)
     if guard_error is not None:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": guard_error,
             "error": None,
         }
     if not no_open_pr:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "open PR present for bound worktree branch",
             "error": None,
         }

     if not reap_worktrees._is_head_reachable_from_remote(bound_path):
         return {
             "path": str(bound_path),
             "action": "skipped",
             "reason": "unpushed_head",
             "error": None,
         }

     if apply:
         live_cwds = reap_worktrees._live_cwd_paths(repo_root)
         if live_cwds is None:
             return {
                 "path": str(bound_path),
                 "action": "retained",
                 "reason": "process-CWD activity probe unavailable",
                 "error": None,
             }
         resolved = bound_path.resolve()
         if any(_cwd_within(Path(cwd), resolved) for cwd in live_cwds):
             return {
                 "path": str(bound_path),
                 "action": "retained",
                 "reason": "live process holds worktree",
                 "error": None,
             }

     try:
         result = reap_worktrees.reap_success_worktree(
             repo_root=repo_root,
             worktree_path=bound_path,
             reason=reason,
             apply=apply,
         )
     except RuntimeError as exc:
         return {
             "path": str(bound_path),
             "action": "retained",
             "reason": "canonical P0 reaper guard failed",
             "error": str(exc),
         }
     return {
         "path": result.path,
         "action": result.action,
         "reason": result.reason,
         "error": result.error,
         "pr": result.pr,
         "recovery_ref": result.recovery_ref,
     }


 def _cwd_within(cwd: Path, worktree: Path) -> bool:
     try:
         cwd.resolve().relative_to(worktree)
     except ValueError:
         return False
     return True


 def _reap_acp_runtime_worktrees(
     *,
     task_id: str,
     state: dict[str, Any],
     repo_root: Path,
     apply: bool,
 ) -> list[dict[str, Any]]:
     """Evaluate and optionally reap ACP runtime worktrees bound in task state."""
     status = state.get("status")
     status_str = str(status) if status is not None else None

     if status_str in _ACTIVE_STATUSES or status_str in (None, ""):
         return []
     if status_str not in _TERMINAL_STATUSES:
         return []

     results: list[dict[str, Any]] = []
     for path in _acp_runtime_paths_from_state(state):
         if not path.exists():
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "bound ACP runtime path does not exist",
                     "error": None,
                 }
             )
             continue

         if not _is_under_acp_runtime_root(path, repo_root):
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "unknown ownership: outside .worktrees/dispatch/acp/",
                     "error": None,
                 }
             )
             continue

         if not _is_registered_worktree(path, repo_root):
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "unknown ownership: not a registered git worktree",
                     "error": None,
                 }
             )
             continue

         dirty = _worktree_is_dirty(path, ignore_deleted_tracked=True)
         if dirty is None:
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "unable to determine worktree cleanliness",
                     "error": None,
                 }
             )
             continue
         if dirty:
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "worktree has uncommitted changes",
                     "error": None,
                 }
             )
             continue

         liveness = _probe_path_liveness(path)
         if liveness is True:
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "live process holds path",
                     "error": None,
                 }
             )
             continue
         if liveness is None:
             results.append(
                 {
                     "path": str(path),
                     "action": "retained",
                     "reason": "liveness probe failed",
                     "error": None,
                 }
             )
             continue

         if not apply:
             results.append(
                 {
                     "path": str(path),
                     "action": "would_remove",
                     "reason": "task terminal, path clean, and process gone",
                     "error": None,
                 }
             )
             continue

         _unlock_worktree(path, repo_root)
         ok, error = _remove_worktree(path, repo_root)
         results.append(
             {
                 "path": str(path),
                 "action": "removed" if ok else "error",
                 "reason": "task terminal, path clean, and process gone",
                 "error": error,
             }
         )
     return results


 def post_task_reap(
     task_id: str,
     *,
     tasks_dir: Path = _TASKS_DIR,
     repo_root: Path = ROOT,
     apply: bool = False,
     include_acp_runtime: bool = True,
 ) -> dict[str, Any]:
     """Return a reap report for ``task_id``; delete only when ``apply`` is True."""
     state = _load_task_state(tasks_dir, task_id)
     if state is None:
         return {
             "task_id": task_id,
             "task_status": None,
             "apply": apply,
             "main_worktree": {
                 "path": None,
                 "action": "retained",
                 "reason": "no task state file found",
                 "error": None,
             },
             "acp_runtimes": [],
             "errors": [],
         }

     main_result = _reap_main_worktree(
         task_id=task_id,
         state=state,
         repo_root=repo_root,
         apply=apply,
     )
     acp_results: list[dict[str, Any]] = []
     if include_acp_runtime:
         acp_results = _reap_acp_runtime_worktrees(
             task_id=task_id,
             state=state,
             repo_root=repo_root,
             apply=apply,
         )

     errors: list[str] = []
     if main_result.get("error"):
         errors.append(f"main worktree: {main_result['error']}")
     for item in acp_results:
         if item.get("error"):
             errors.append(f"acp runtime {item['path']}: {item['error']}")

     return {
         "task_id": task_id,
         "task_status": state.get("status"),
         "apply": apply,
         "main_worktree": main_result,
         "acp_runtimes": acp_results,
         "errors": errors,
     }


 def main(argv: list[str] | None = None) -> int:
     parser = argparse.ArgumentParser(description=__doc__)
     parser.add_argument("--task-id", required=True, help="Task id whose worktree should be reaped")
     parser.add_argument(
         "--apply",
         action="store_true",
         help="Actually remove worktrees (default: dry-run)",
     )
     parser.add_argument(
         "--tasks-dir",
         type=Path,
         default=_TASKS_DIR,
         help="batch_state/tasks directory",
     )
     parser.add_argument(
         "--repo-root",
         type=Path,
         default=ROOT,
         help="Repository root (primary checkout)",
     )
     parser.add_argument(
         "--include-acp-runtime",
         default=True,
         action=argparse.BooleanOptionalAction,
         help="Also evaluate ACP runtime paths listed in task state (default: on)",
     )
     args = parser.parse_args(argv)

     report = post_task_reap(
         args.task_id,
         tasks_dir=args.tasks_dir,
         repo_root=args.repo_root,
         apply=args.apply,
         include_acp_runtime=args.include_acp_runtime,
     )

     print(json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True))
     return 1 if report["errors"] else 0


 if __name__ == "__main__":
     raise SystemExit(main())

display.text:
#!/usr/bin/env python3
"""Safe post-task reaper for dispatch worktrees.

Reaps the dispatch worktree bound to one task_id only after the task is terminal,
the worktree is clean, and (when a PID is recorded) the process is dead.  ACP
runtime paths are reaped only when they are explicitly listed in the task state
(``acp_runtime_paths``), the task is terminal, the path is clean, and no live
process holds it.

A terminal dispatch worktree is reaped even when its task never opened a GitHub
PR (measure-only, timeout, cancelled, …) as long as ownership, cleanliness, and
dead-PID guards all hold and no open PR is present.  The deletion itself always
goes through the canonical P0 reaper boundary.

Default mode is dry-run; pass --apply to delete anything.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
from pathlib import Path
from typing import Any

from scripts.common.repo_root import main_checkout_root
from scripts.orchestration import reap_worktrees, reaper_lifecycle
from scripts.path_safety import assert_delete_target

ROOT = main_checkout_root(Path(__file__).resolve().parents[2])
_TASKS_DIR = ROOT / "batch_state" / "tasks"
_DISPATCH_WORKTREES_ROOT = ROOT / ".worktrees" / "dispatch"
_ACP_RUNTIME_ROOT = _DISPATCH_WORKTREES_ROOT / "acp"

_ACTIVE_STATUSES = frozenset({"spawning", "running"})
_TERMINAL_STATUSES = frozenset(
    {
        "done",
        "failed",
        "timeout",
        "rate_limited",
        "cancelled",
        "crashed",
        "dry_run",
        "needs_finalize",
        "no_deliverable",
    }
)

_GIT_ENV_DENYLIST = {
    "GIT_DIR",
    "GIT_WORK_TREE",
    "GIT_INDEX_FILE",
    "GIT_OBJECT_DIRECTORY",
    "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_NAMESPACE",
    "GIT_CEILING_DIRECTORIES",
    "GIT_DISCOVERY_ACROSS_FILESYSTEM",
    "GIT_COMMON_DIR",
}


def _sanitized_git_env() -> dict[str, str]:
    return {
        key: value
        for key, value in os.environ.items()
        if key not in _GIT_ENV_DENYLIST and not key.startswith("PRE_COMMIT")
    }


def _run_git(
    args: list[str],
    *,
    cwd: Path,
    timeout: int | None = 30,
    check: bool = False,
) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", *args],
        cwd=cwd,
        capture_output=True,
        text=True,
        check=check,
        timeout=timeout,
        env=_sanitized_git_env(),
    )


def _load_task_state(tasks_dir: Path, task_id: str) -> dict[str, Any] | None:
    safe = task_id.replace("/", "_").replace("\\", "_")
    path = tasks_dir / f"{safe}.json"
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    return data if isinstance(data, dict) else None


def _worktree_path_from_state(state: dict[str, Any]) -> Path | None:
    """Return the bound worktree path recorded in task state, if any."""
    for key in ("worktree_path", "cwd"):
        value = state.get(key)
        if value:
            try:
                return Path(str(value)).resolve()
            except OSError:
                continue
    return None


def _acp_runtime_paths_from_state(state: dict[str, Any]) -> list[Path]:
    """Return ACP runtime paths explicitly bound to this task in state.

    Paths are taken from ``acp_runtime_paths`` (a list of strings).  Name or
    substring matching is never used; an unbound path is not ours to reap.
    """
    raw = state.get("acp_runtime_paths")
    if not isinstance(raw, list):
        return []
    candidates: list[Path] = []
    for item in raw:
        if not item:
            continue
        try:
            candidates.append(Path(str(item)).resolve())
        except OSError:
            continue
    return candidates


def _is_under_dispatch_worktrees(path: Path) -> bool:
    """True for paths inside .worktrees/dispatch/ but outside the ACP runtime subtree."""
    try:
        rel = path.resolve().relative_to(_DISPATCH_WORKTREES_ROOT)
    except ValueError:
        return False
    return rel.parts[:1] != ("acp",)


def _acp_runtime_root(repo_root: Path) -> Path:
    """Return the dedicated ACP-runtime subtree for one repository root."""
    return repo_root.resolve() / ".worktrees" / "dispatch" / "acp"


def _is_under_acp_runtime_root(path: Path, repo_root: Path = ROOT) -> bool:
    """True for paths inside .worktrees/dispatch/acp/."""
    runtime_root = _acp_runtime_root(repo_root).resolve()
    try:
        resolved_path = path.resolve()
        resolved_path.relative_to(runtime_root)
    except ValueError:
        return False
    return resolved_path != runtime_root


def _is_registered_worktree(path: Path, repo_root: Path) -> bool:
    """True when path is a registered git worktree."""
    proc = _run_git(["worktree", "list", "--porcelain"], cwd=repo_root)
    if proc.returncode != 0:
        return False
    resolved = path.resolve()
    for line in (proc.stdout or "").splitlines():
        if line.startswith("worktree "):
            candidate = Path(line[len("worktree ") :].strip()).resolve()
            if candidate == resolved:
                return True
    return False


def _worktree_is_dirty(path: Path, *, ignore_deleted_tracked: bool = False) -> bool | None:
    proc = _run_git(["status", "--porcelain"], cwd=path)
    if proc.returncode != 0:
        return None
    lines = [line for line in (proc.stdout or "").splitlines() if line.strip()]
    if ignore_deleted_tracked:
        # No-checkout ACP runtime worktrees report every tracked file as deleted.
        # Ignore those baseline deletions; flag only untracked/modified additions.
        lines = [line for line in lines if not (line[0] == "D" or line[1] == "D")]
    return bool(lines)


def _git_worktree_is_locked(path: Path, repo_root: Path) -> bool:
    """Return True if git reports the worktree as locked.  Fail closed."""
    proc = _run_git(["worktree", "list", "--porcelain"], cwd=repo_root)
    if proc.returncode != 0:
        return True
    resolved = path.resolve()
    entry_path: Path | None = None
    locked = False
    for line in (proc.stdout or "").splitlines():
        if line.startswith("worktree "):
            if entry_path == resolved:
                return locked
            entry_path = Path(line[len("worktree ") :].strip()).resolve()
            locked = False
        elif line.startswith("locked"):
            locked = True
    if entry_path == resolved:
        return locked
    return True


def _pid_alive(pid: int) -> bool | None:
    """Return True if ``pid`` is alive, False if dead, None if probe failed.

    Fail-closed callers must treat ``None`` as 'retain'.
    """
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return None
    return True


def _probe_path_liveness(path: Path) -> bool | None:
    """Return True if a live process holds ``path``, False if not, None on error.

    Uses ``lsof +D`` when available.  Any probe failure (missing binary, timeout,
    nonzero exit, or subprocess error) returns ``None`` so the caller can fail
    closed and retain the path.
    """
    try:
        proc = subprocess.run(
            ["lsof", "+D", str(path)],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.SubprocessError):
        return None
    if proc.returncode != 0:
        return None
    return any(line and not line.startswith("COMMAND") for line in (proc.stdout or "").splitlines())


def _unlock_worktree(path: Path, repo_root: Path) -> None:
    """Best-effort unlock of a git worktree before removal."""
    _run_git(["worktree", "unlock", str(path)], cwd=repo_root)


def _remove_worktree(path: Path, repo_root: Path) -> tuple[bool, str | None]:
    """Force-remove one state-bound ACP runtime beneath its dedicated subtree.

    This is deliberately not the regular dispatch deletion path: callers must
    first establish terminal task ownership, cleanliness, and no live process.
    Regular dispatch worktrees always go through ``reap_worktrees`` instead.
    """
    if not _is_under_acp_runtime_root(path, repo_root):
        return False, "ACP runtime path is outside .worktrees/dispatch/acp/"
    try:
        target = assert_delete_target(path, repo_root=repo_root)
    except ValueError as exc:
        return False, f"delete guard refused ACP runtime target: {exc}"
    cmd = ["worktree", "remove", "--force", str(target)]
    proc = _run_git(cmd, cwd=repo_root)
    if proc.returncode != 0:
        detail = (proc.stderr or proc.stdout or "git worktree remove failed").strip()
        return False, detail
    if path.exists():
        return False, f"worktree path still exists after remove: {path}"
    return True, None


def _parse_state_pid(state: dict[str, Any]) -> int | None:
    """Return a positive integer PID from task state, or None."""
    raw = state.get("pid")
    if isinstance(raw, bool):
        return None
    if isinstance(raw, int):
        return raw if raw > 0 else None
    if isinstance(raw, str) and raw.isdigit():
        return int(raw) if int(raw) > 0 else None
    return None


def _reap_main_worktree(
    *,
    task_id: str,
    state: dict[str, Any],
    repo_root: Path,
    apply: bool,
) -> dict[str, Any]:
    """Evaluate and optionally reap the dispatch worktree bound to task_id."""
    status = state.get("status")
    status_str = str(status) if status is not None else None

    if status_str in _ACTIVE_STATUSES or status_str in (None, ""):
        return {
            "path": None,
            "action": "retained",
            "reason": f"task still active (status={status_str})",
            "error": None,
        }
    if status_str not in _TERMINAL_STATUSES:
        return {
            "path": None,
            "action": "retained",
            "reason": f"task status not terminal (status={status_str})",
            "error": None,
        }

    bound_path = _worktree_path_from_state(state)
    if bound_path is None:
        return {
            "path": None,
            "action": "retained",
            "reason": "unknown ownership: no worktree_path/cwd in task state",
            "error": None,
        }

    if not bound_path.exists():
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "bound worktree path does not exist",
            "error": None,
        }

    if not _is_under_dispatch_worktrees(bound_path):
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "unknown ownership: path is outside .worktrees/dispatch/",
            "error": None,
        }

    state_task_id = state.get("task_id")
    if state_task_id not in (None, task_id):
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "unknown ownership: task-state task_id does not match requested task",
            "error": None,
        }
    try:
        relative = bound_path.relative_to(_DISPATCH_WORKTREES_ROOT)
    except ValueError:  # guarded above; retain if the filesystem changed.
        relative = ()
    expected_agent = str(state.get("agent") or "")
    if (
        len(relative.parts) != 2
        or relative.parts[1] != task_id
        or not expected_agent
        or relative.parts[0] != expected_agent
    ):
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "unknown ownership: task binding does not match dispatch path",
            "error": None,
        }

    if reaper_lifecycle.is_reap_pending(repo_root, bound_path):
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "reap-pending reservation blocks a new task bind",
            "error": None,
        }

    if not _is_registered_worktree(bound_path, repo_root):
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "unknown ownership: path is not a registered git worktree",
            "error": None,
        }

    if _git_worktree_is_locked(bound_path, repo_root):
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "registered worktree is locked",
            "error": None,
        }

    dirty = _worktree_is_dirty(bound_path)
    if dirty is None:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "unable to determine worktree cleanliness",
            "error": None,
        }
    if dirty:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "worktree has uncommitted changes",
            "error": None,
        }

    pid = _parse_state_pid(state)
    if pid is not None:
        alive = _pid_alive(pid)
        if alive is True:
            return {
                "path": str(bound_path),
                "action": "retained",
                "reason": f"live process holds worktree (pid={pid})",
                "error": None,
            }
        if alive is None:
            return {
                "path": str(bound_path),
                "action": "retained",
                "reason": f"liveness probe failed for recorded pid={pid}",
                "error": None,
            }

    row = _reap_via_canonical(
        repo_root=repo_root,
        bound_path=bound_path,
        apply=apply,
        include_terminal_dispatches=True,
    )
    if row is None:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "canonical P0 reaper did not evaluate bound path",
            "error": None,
        }

    # The canonical reaper only reaps a settled dispatch without a PR when its
    # active-task API probe succeeds and the status is in its narrow terminal
    # set (done/failed/no_deliverable).  post_task_reap has already proven the
    # broader terminal contract itself: status is terminal, the bound tree is
    # clean, and the recorded PID is dead.  When the canonical reaper declines
    # solely because no GitHub PR qualifies, drive the same guarded deletion
    # through its public success-worktree boundary, after re-proving that no
    # open PR appeared and (on apply) that no live process holds the tree.
    if row["action"] == "skipped" and row["reason"] == "no reap condition matched":
        return _reap_terminal_without_pr(
            task_id=task_id,
            status_str=status_str,
            bound_path=bound_path,
            row=row,
            repo_root=repo_root,
            apply=apply,
            branch=row.get("branch") or f"{expected_agent}/{task_id}",
        )
    return row


def _reap_via_canonical(
    *,
    repo_root: Path,
    bound_path: Path,
    apply: bool,
    include_terminal_dispatches: bool,
) -> dict[str, Any] | None:
    """Delegate to the canonical P0 reaper for one bound dispatch worktree."""
    try:
        rows = reap_worktrees.reap_worktrees(
            repo_root=repo_root,
            apply=apply,
            preserve_then_reap=False,
            prune_merged_branches=True,
            target_paths=[bound_path],
            merged_pr_only=True,
            include_terminal_dispatches=include_terminal_dispatches,
            require_activity_probe=apply,
        )
    except RuntimeError as exc:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "canonical P0 reaper guard failed",
            "error": str(exc),
        }
    if not rows:
        return None
    row = rows[0]
    return {
        "path": row.path,
        "action": row.action,
        "reason": row.reason,
        "error": row.error,
        "pr": row.pr,
        "recovery_ref": row.recovery_ref,
        "branch": row.branch,
    }


def _no_open_pr_for_branch(
    *,
    repo_root: Path,
    branch: str | None,
) -> tuple[bool, str | None]:
    """Return (no_open_pr, failure) for the branch that owns the bound tree.

    Reuses the canonical reaper's candidate derivation so detached and
    dispatch-layout worktrees are checked under the same branch names that the
    canonical path would have probed.  A probe error is fail-closed.
    """
    if not branch:
        return False, "no branch identity to probe for an open PR"
    prs, error = reap_worktrees._query_pr_states(repo_root, branch)
    if error is not None:
        return False, f"PR guard unavailable; {error}"
    return all(pr.state != "OPEN" for pr in prs), None


def _reap_terminal_without_pr(
    *,
    task_id: str,
    status_str: str,
    bound_path: Path,
    row: dict[str, Any],
    repo_root: Path,
    apply: bool,
    branch: str | None,
) -> dict[str, Any]:
    """Reap a clean, dead-PID, dispatch-layout worktree that never had a PR."""
    reason = f"settled dispatch task-id={task_id} status={status_str}"

    no_open_pr, guard_error = _no_open_pr_for_branch(repo_root=repo_root, branch=branch)
    if guard_error is not None:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": guard_error,
            "error": None,
        }
    if not no_open_pr:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "open PR present for bound worktree branch",
            "error": None,
        }

    if not reap_worktrees._is_head_reachable_from_remote(bound_path):
        return {
            "path": str(bound_path),
            "action": "skipped",
            "reason": "unpushed_head",
            "error": None,
        }

    if apply:
        live_cwds = reap_worktrees._live_cwd_paths(repo_root)
        if live_cwds is None:
            return {
                "path": str(bound_path),
                "action": "retained",
                "reason": "process-CWD activity probe unavailable",
                "error": None,
            }
        resolved = bound_path.resolve()
        if any(_cwd_within(Path(cwd), resolved) for cwd in live_cwds):
            return {
                "path": str(bound_path),
                "action": "retained",
                "reason": "live process holds worktree",
                "error": None,
            }

    try:
        result = reap_worktrees.reap_success_worktree(
            repo_root=repo_root,
            worktree_path=bound_path,
            reason=reason,
            apply=apply,
        )
    except RuntimeError as exc:
        return {
            "path": str(bound_path),
            "action": "retained",
            "reason": "canonical P0 reaper guard failed",
            "error": str(exc),
        }
    return {
        "path": result.path,
        "action": result.action,
        "reason": result.reason,
        "error": result.error,
        "pr": result.pr,
        "recovery_ref": result.recovery_ref,
    }


def _cwd_within(cwd: Path, worktree: Path) -> bool:
    try:
        cwd.resolve().relative_to(worktree)
    except ValueError:
        return False
    return True


def _reap_acp_runtime_worktrees(
    *,
    task_id: str,
    state: dict[str, Any],
    repo_root: Path,
    apply: bool,
) -> list[dict[str, Any]]:
    """Evaluate and optionally reap ACP runtime worktrees bound in task state."""
    status = state.get("status")
    status_str = str(status) if status is not None else None

    if status_str in _ACTIVE_STATUSES or status_str in (None, ""):
        return []
    if status_str not in _TERMINAL_STATUSES:
        return []

    results: list[dict[str, Any]] = []
    for path in _acp_runtime_paths_from_state(state):
        if not path.exists():
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "bound ACP runtime path does not exist",
                    "error": None,
                }
            )
            continue

        if not _is_under_acp_runtime_root(path, repo_root):
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "unknown ownership: outside .worktrees/dispatch/acp/",
                    "error": None,
                }
            )
            continue

        if not _is_registered_worktree(path, repo_root):
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "unknown ownership: not a registered git worktree",
                    "error": None,
                }
            )
            continue

        dirty = _worktree_is_dirty(path, ignore_deleted_tracked=True)
        if dirty is None:
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "unable to determine worktree cleanliness",
                    "error": None,
                }
            )
            continue
        if dirty:
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "worktree has uncommitted changes",
                    "error": None,
                }
            )
            continue

        liveness = _probe_path_liveness(path)
        if liveness is True:
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "live process holds path",
                    "error": None,
                }
            )
            continue
        if liveness is None:
            results.append(
                {
                    "path": str(path),
                    "action": "retained",
                    "reason": "liveness probe failed",
                    "error": None,
                }
            )
            continue

        if not apply:
            results.append(
                {
                    "path": str(path),
                    "action": "would_remove",
                    "reason": "task terminal, path clean, and process gone",
                    "error": None,
                }
            )
            continue

        _unlock_worktree(path, repo_root)
        ok, error = _remove_worktree(path, repo_root)
        results.append(
            {
                "path": str(path),
                "action": "removed" if ok else "error",
                "reason": "task terminal, path clean, and process gone",
                "error": error,
            }
        )
    return results


def post_task_reap(
    task_id: str,
    *,
    tasks_dir: Path = _TASKS_DIR,
    repo_root: Path = ROOT,
    apply: bool = False,
    include_acp_runtime: bool = True,
) -> dict[str, Any]:
    """Return a reap report for ``task_id``; delete only when ``apply`` is True."""
    state = _load_task_state(tasks_dir, task_id)
    if state is None:
        return {
            "task_id": task_id,
            "task_status": None,
            "apply": apply,
            "main_worktree": {
                "path": None,
                "action": "retained",
                "reason": "no task state file found",
                "error": None,
            },
            "acp_runtimes": [],
            "errors": [],
        }

    main_result = _reap_main_worktree(
        task_id=task_id,
        state=state,
        repo_root=repo_root,
        apply=apply,
    )
    acp_results: list[dict[str, Any]] = []
    if include_acp_runtime:
        acp_results = _reap_acp_runtime_worktrees(
            task_id=task_id,
            state=state,
            repo_root=repo_root,
            apply=apply,
        )

    errors: list[str] = []
    if main_result.get("error"):
        errors.append(f"main worktree: {main_result['error']}")
    for item in acp_results:
        if item.get("error"):
            errors.append(f"acp runtime {item['path']}: {item['error']}")

    return {
        "task_id": task_id,
        "task_status": state.get("status"),
        "apply": apply,
        "main_worktree": main_result,
        "acp_runtimes": acp_results,
        "errors": errors,
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--task-id", required=True, help="Task id whose worktree should be reaped")
    parser.add_argument(
        "--apply",
        action="store_true",
        help="Actually remove worktrees (default: dry-run)",
    )
    parser.add_argument(
        "--tasks-dir",
        type=Path,
        default=_TASKS_DIR,
        help="batch_state/tasks directory",
    )
    parser.add_argument(
        "--repo-root",
        type=Path,
        default=ROOT,
        help="Repository root (primary checkout)",
    )
    parser.add_argument(
        "--include-acp-runtime",
        default=True,
        action=argparse.BooleanOptionalAction,
        help="Also evaluate ACP runtime paths listed in task state (default: on)",
    )
    args = parser.parse_args(argv)

    report = post_task_reap(
        args.task_id,
        tasks_dir=args.tasks_dir,
        repo_root=args.repo_root,
        apply=args.apply,
        include_acp_runtime=args.include_acp_runtime,
    )

    print(json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True))
